// Procedural sounds, rendered once with an OfflineAudioContext (licence-clean: generated by code).

const HOOF_SECONDS = 0.12;

const NOISE_SEED = 0x2545f491;

/** Deterministic noise: a seeded LCG so every render is identical (each take may use its own seed). */
function fillNoise(data: Float32Array, seed = NOISE_SEED): void {
  let s = seed >>> 0;
  for (let i = 0; i < data.length; i++) {
    s = (Math.imul(s, 1664525) + 1013904223) >>> 0;
    data[i] = (s / 4294967296) * 2 - 1;
  }
}

/**
 * A hoof clop: a 100 ms noise burst through a band-pass (1400 Hz + 120 Hz per variant, Q 1.2,
 * 2 ms attack, exponential decay by 70 ms) plus a sine thump falling from 170 to 60 Hz over 90 ms.
 * `variant` is 0, 1 or 2.
 */
export async function renderHoof(variant: number, sampleRate = 44100): Promise<AudioBuffer> {
  const length = Math.ceil(HOOF_SECONDS * sampleRate);
  const ctx = new OfflineAudioContext(1, length, sampleRate);

  const noise = ctx.createBuffer(1, Math.ceil(0.1 * sampleRate), sampleRate);
  fillNoise(noise.getChannelData(0));
  const source = ctx.createBufferSource();
  source.buffer = noise;
  const band = ctx.createBiquadFilter();
  band.type = "bandpass";
  band.frequency.value = 1400 + 120 * variant;
  band.Q.value = 1.2;
  const noiseGain = ctx.createGain();
  noiseGain.gain.setValueAtTime(0, 0);
  noiseGain.gain.linearRampToValueAtTime(0.9, 0.002);
  noiseGain.gain.exponentialRampToValueAtTime(0.001, 0.07);
  source.connect(band).connect(noiseGain).connect(ctx.destination);
  source.start(0);

  const thump = ctx.createOscillator();
  thump.type = "sine";
  thump.frequency.setValueAtTime(170, 0);
  thump.frequency.exponentialRampToValueAtTime(60, 0.09);
  const thumpGain = ctx.createGain();
  thumpGain.gain.setValueAtTime(0, 0);
  thumpGain.gain.linearRampToValueAtTime(0.8, 0.003);
  thumpGain.gain.exponentialRampToValueAtTime(0.001, 0.11);
  thump.connect(thumpGain).connect(ctx.destination);
  thump.start(0);
  thump.stop(HOOF_SECONDS);

  return ctx.startRendering();
}

// --- Hoof versions B to D (recette 3 de Romain, 2026-10-15: « Page d'essai à choix ») ---
//
// A real clop is rarely one strike: the heel lands, then the toe, 15 to 40 ms later (the « clip-clop »).
// Each version below is two strikes of the same surface, the second softer, with its own noise seed
// per take, so the three takes of a version differ in grain and in rhythm, not only in pitch.

type Strike = {
  /** Start of the strike, in seconds. */
  at: number;
  /** Level of the whole strike (the toe is softer than the heel). */
  level: number;
};

/** The heel and toe strikes of one take: the gap and the toe's level move from take to take. */
function strikes(take: number, gapMs: [number, number, number], toe: number): Strike[] {
  return [
    { at: 0, level: 1 },
    { at: (gapMs[take % 3] as number) / 1000, level: toe - 0.08 * (take % 3) },
  ];
}

/** A noise burst through a band-pass, with a fast attack and an exponential decay. */
function noiseHit(
  ctx: OfflineAudioContext,
  out: AudioNode,
  hit: {
    at: number;
    seed: number;
    freq: number;
    q: number;
    gain: number;
    decay: number;
    attack?: number;
  },
): void {
  const source = ctx.createBufferSource();
  const buffer = ctx.createBuffer(
    1,
    Math.ceil((hit.decay + 0.02) * ctx.sampleRate),
    ctx.sampleRate,
  );
  fillNoise(buffer.getChannelData(0), hit.seed);
  source.buffer = buffer;
  const band = ctx.createBiquadFilter();
  band.type = "bandpass";
  band.frequency.value = hit.freq;
  band.Q.value = hit.q;
  const env = ctx.createGain();
  const attack = hit.attack ?? 0.002;
  env.gain.setValueAtTime(0, hit.at);
  env.gain.linearRampToValueAtTime(hit.gain, hit.at + attack);
  env.gain.exponentialRampToValueAtTime(0.001, hit.at + hit.decay);
  source.connect(band).connect(env).connect(out);
  source.start(hit.at);
}

/** A sine whose pitch falls (a thump) or holds (a ring), with an exponential decay. */
function toneHit(
  ctx: OfflineAudioContext,
  out: AudioNode,
  hit: { at: number; from: number; to: number; gain: number; decay: number },
): void {
  const osc = ctx.createOscillator();
  osc.type = "sine";
  osc.frequency.setValueAtTime(hit.from, hit.at);
  if (hit.to !== hit.from) osc.frequency.exponentialRampToValueAtTime(hit.to, hit.at + hit.decay);
  const env = ctx.createGain();
  env.gain.setValueAtTime(0, hit.at);
  env.gain.linearRampToValueAtTime(hit.gain, hit.at + 0.002);
  env.gain.exponentialRampToValueAtTime(0.001, hit.at + hit.decay);
  osc.connect(env).connect(out);
  osc.start(hit.at);
  osc.stop(hit.at + hit.decay + 0.01);
}

const HOOF_PEAK = 0.85;

/**
 * B, « sur la terre »: a hoof on packed earth. Soft and low: noise through a wide band-pass around
 * 700 to 820 Hz (Q 0.9) with a 5 ms attack and a 110 ms decay, under a low-pass at 2 kHz that takes
 * the click out, a deep thump falling from 120 to 45 Hz, and a faint gritty tail (crumbs of earth,
 * high band, very low). Takes: the band moves by 60 Hz, the heel-toe gap by 8 ms.
 */
export async function renderHoofTerre(take: number, sampleRate = 44100): Promise<AudioBuffer> {
  const seconds = 0.22;
  const buffer = await renderToBuffer(Math.ceil(seconds * sampleRate), sampleRate, (ctx) => {
    const soft = ctx.createBiquadFilter();
    soft.type = "lowpass";
    soft.frequency.value = 2000;
    soft.connect(ctx.destination);
    for (const [n, strike] of strikes(take, [34, 26, 42], 0.62).entries()) {
      noiseHit(ctx, soft, {
        at: strike.at,
        seed: 0x9e3779b1 + take * 977 + n * 131,
        freq: 700 + 60 * take,
        q: 0.9,
        gain: 0.9 * strike.level,
        decay: 0.11,
        attack: 0.005,
      });
      toneHit(ctx, ctx.destination, {
        at: strike.at,
        from: 120,
        to: 45,
        gain: 0.9 * strike.level,
        decay: 0.12,
      });
      noiseHit(ctx, ctx.destination, {
        at: strike.at + 0.012,
        seed: 0x1234567 + take * 31 + n,
        freq: 3500,
        q: 0.7,
        gain: 0.06 * strike.level,
        decay: 0.09,
      });
    }
  });
  normalize(buffer.getChannelData(0), HOOF_PEAK);
  return buffer;
}

// --- Normalisation (pure, tested in Node) ---

/** Scale `data` in place so its largest absolute sample equals `peak` (silence stays silence). */
export function normalize(data: Float32Array, peak: number): void {
  let max = 0;
  for (const sample of data) max = Math.max(max, Math.abs(sample));
  if (max === 0) return;
  const factor = peak / max;
  for (let i = 0; i < data.length; i++) data[i] = (data[i] as number) * factor;
}

async function renderToBuffer(
  length: number,
  sampleRate: number,
  build: (ctx: OfflineAudioContext) => void,
): Promise<AudioBuffer> {
  const ctx = new OfflineAudioContext(1, length, sampleRate);
  build(ctx);
  return ctx.startRendering();
}

function noiseBuffer(ctx: OfflineAudioContext, seconds: number): AudioBuffer {
  const buffer = ctx.createBuffer(1, Math.ceil(seconds * ctx.sampleRate), ctx.sampleRate);
  fillNoise(buffer.getChannelData(0));
  return buffer;
}

// --- Neighs (RESEARCH Appendix D) ---

export type NeighKind = "sortie" | "ruade" | "plainte" | "joyeux" | "fete" | "surpris";

type NeighSpec = {
  duration: number;
  /** Fundamental contour: [seconds, Hz] points joined by exponential ramps. */
  contour: [number, number][];
  vibratoHz: number;
  vibratoDepthHz: number;
  /** Three parallel band-pass formants, swept to `target` by 30 % of the duration, then back to 0.8 of the start. */
  formants: { freq: number; q: number; gain: number; target: number }[];
  /** Breath noise level (band-passed at 3 kHz) relative to the voiced part. */
  breath: number;
  attack: number;
  /** Fraction of the duration held at full level before the exponential release. */
  hold: number;
};

const formants = (targets: [number, number, number]): NeighSpec["formants"] => [
  { freq: 650, q: 5, gain: 1.0, target: targets[0] },
  { freq: 1300, q: 6, gain: 0.7, target: targets[1] },
  { freq: 2700, q: 8, gain: 0.4, target: targets[2] },
];

const NEIGHS: Record<NeighKind, NeighSpec> = {
  // Stable exit: the full neigh, rising then falling, with vibrato.
  sortie: {
    duration: 1.1,
    contour: [
      [0, 420],
      [0.25, 900],
      [0.5, 700],
      [1.1, 330],
    ],
    vibratoHz: 22,
    vibratoDepthHz: 18,
    formants: formants([1100, 2000, 3200]),
    breath: 0.12,
    attack: 0.06,
    hold: 0.65,
  },
  // Rear-up: a short, noise-heavy snort.
  ruade: {
    duration: 0.25,
    contour: [
      [0, 260],
      [0.06, 520],
      [0.25, 230],
    ],
    vibratoHz: 0,
    vibratoDepthHz: 0,
    formants: formants([1000, 1900, 3000]),
    breath: 1.6,
    attack: 0.01,
    hold: 0.5,
  },
  // Captured pawn: lower, falling, trembling.
  plainte: {
    duration: 1.0,
    contour: [
      [0, 560],
      [0.15, 640],
      [0.45, 430],
      [1.0, 220],
    ],
    vibratoHz: 26,
    vibratoDepthHz: 22,
    formants: formants([800, 1500, 2500]),
    breath: 0.1,
    attack: 0.08,
    hold: 0.5,
  },
  // Pawn home: shorter, 1.4 times higher.
  joyeux: {
    duration: 0.75,
    contour: [
      [0, 590],
      [0.14, 1260],
      [0.3, 980],
      [0.75, 460],
    ],
    vibratoHz: 22,
    vibratoDepthHz: 22,
    formants: formants([1300, 2300, 3400]),
    breath: 0.1,
    attack: 0.04,
    hold: 0.6,
  },
  // Fourth pawn home: the joyful neigh, longer, with a second rise.
  fete: {
    duration: 1.7,
    contour: [
      [0, 600],
      [0.2, 1300],
      [0.45, 1000],
      [0.7, 1350],
      [1.0, 1050],
      [1.7, 480],
    ],
    vibratoHz: 22,
    vibratoDepthHz: 24,
    formants: formants([1300, 2300, 3400]),
    breath: 0.1,
    attack: 0.05,
    hold: 0.7,
  },
  // Valet swap: a short surprised squeak, rising only.
  surpris: {
    duration: 0.35,
    contour: [
      [0, 430],
      [0.12, 800],
      [0.35, 1150],
    ],
    vibratoHz: 24,
    vibratoDepthHz: 14,
    formants: formants([1200, 2200, 3300]),
    breath: 0.1,
    attack: 0.02,
    hold: 0.75,
  },
};

const NEIGH_PEAK = 0.7;

/**
 * A synthesized neigh: a sawtooth with the spec's pitch contour and vibrato through three swept
 * formants, plus band-passed breath noise, shaped by an attack/hold/release envelope.
 */
export async function renderNeigh(kind: NeighKind, sampleRate = 44100): Promise<AudioBuffer> {
  const spec = NEIGHS[kind];
  const length = Math.ceil((spec.duration + 0.05) * sampleRate);
  const buffer = await renderToBuffer(length, sampleRate, (ctx) => {
    const envelope = ctx.createGain();
    envelope.gain.setValueAtTime(0, 0);
    envelope.gain.linearRampToValueAtTime(1, spec.attack);
    envelope.gain.setValueAtTime(1, spec.hold * spec.duration);
    envelope.gain.exponentialRampToValueAtTime(0.001, spec.duration);
    envelope.connect(ctx.destination);

    const voice = ctx.createOscillator();
    voice.type = "sawtooth";
    const [first, ...rest] = spec.contour;
    if (first) voice.frequency.setValueAtTime(first[1], first[0]);
    for (const [t, hz] of rest) voice.frequency.exponentialRampToValueAtTime(hz, t);
    if (spec.vibratoDepthHz > 0) {
      const vibrato = ctx.createOscillator();
      vibrato.frequency.value = spec.vibratoHz;
      const depth = ctx.createGain();
      depth.gain.value = spec.vibratoDepthHz;
      vibrato.connect(depth).connect(voice.frequency);
      vibrato.start(0);
      vibrato.stop(spec.duration);
    }
    for (const formant of spec.formants) {
      const band = ctx.createBiquadFilter();
      band.type = "bandpass";
      band.Q.value = formant.q;
      band.frequency.setValueAtTime(formant.freq, 0);
      band.frequency.linearRampToValueAtTime(formant.target, 0.3 * spec.duration);
      band.frequency.linearRampToValueAtTime(formant.freq * 0.8, spec.duration);
      const level = ctx.createGain();
      level.gain.value = formant.gain;
      voice.connect(band).connect(level).connect(envelope);
    }
    voice.start(0);
    voice.stop(spec.duration);

    const breath = ctx.createBufferSource();
    breath.buffer = noiseBuffer(ctx, spec.duration + 0.05);
    const breathBand = ctx.createBiquadFilter();
    breathBand.type = "bandpass";
    breathBand.frequency.value = 3000;
    breathBand.Q.value = 0.8;
    const breathLevel = ctx.createGain();
    breathLevel.gain.value = spec.breath;
    breath.connect(breathBand).connect(breathLevel).connect(envelope);
    breath.start(0);
  });
  normalize(buffer.getChannelData(0), NEIGH_PEAK);
  return buffer;
}

// --- Cards ---

export type CardKind = "donne" | "pose" | "echange";

const CARD_PEAK = 0.5;

/**
 * Card sounds from short filtered noise: `donne` is a riffle (fourteen quick ticks), `pose` a
 * soft thump (card on felt), `echange` a band-passed sweep (card slid across the table).
 */
export async function renderCard(kind: CardKind, sampleRate = 44100): Promise<AudioBuffer> {
  const seconds = kind === "donne" ? 0.62 : kind === "pose" ? 0.18 : 0.36;
  const buffer = await renderToBuffer(Math.ceil(seconds * sampleRate), sampleRate, (ctx) => {
    if (kind === "donne") {
      const ticks = ctx.createBuffer(1, Math.ceil(seconds * sampleRate), sampleRate);
      const data = ticks.getChannelData(0);
      const noise = new Float32Array(data.length);
      fillNoise(noise);
      let t = 0.02;
      for (let k = 0; k < 14; k++) {
        const start = Math.floor(t * sampleRate);
        const decay = 0.0035 * sampleRate;
        const amplitude = 0.55 + (0.45 * ((k * 7) % 5)) / 4;
        for (let i = 0; i < 0.014 * sampleRate && start + i < data.length; i++) {
          data[start + i] = (noise[start + i] as number) * amplitude * Math.exp(-i / decay);
        }
        t += 0.036 - 0.0008 * k; // the riffle speeds up
      }
      const source = ctx.createBufferSource();
      source.buffer = ticks;
      const high = ctx.createBiquadFilter();
      high.type = "highpass";
      high.frequency.value = 1500;
      const band = ctx.createBiquadFilter();
      band.type = "bandpass";
      band.frequency.value = 3800;
      band.Q.value = 0.7;
      source.connect(high).connect(band).connect(ctx.destination);
      source.start(0);
    } else if (kind === "pose") {
      const source = ctx.createBufferSource();
      source.buffer = noiseBuffer(ctx, 0.05);
      const low = ctx.createBiquadFilter();
      low.type = "lowpass";
      low.frequency.value = 1300;
      const burst = ctx.createGain();
      burst.gain.setValueAtTime(0, 0);
      burst.gain.linearRampToValueAtTime(0.7, 0.002);
      burst.gain.exponentialRampToValueAtTime(0.001, 0.05);
      source.connect(low).connect(burst).connect(ctx.destination);
      source.start(0);
      const thump = ctx.createOscillator();
      thump.frequency.setValueAtTime(150, 0);
      thump.frequency.exponentialRampToValueAtTime(70, 0.1);
      const thumpGain = ctx.createGain();
      thumpGain.gain.setValueAtTime(0, 0);
      thumpGain.gain.linearRampToValueAtTime(0.9, 0.003);
      thumpGain.gain.exponentialRampToValueAtTime(0.001, 0.14);
      thump.connect(thumpGain).connect(ctx.destination);
      thump.start(0);
      thump.stop(seconds);
    } else {
      const source = ctx.createBufferSource();
      source.buffer = noiseBuffer(ctx, seconds);
      const band = ctx.createBiquadFilter();
      band.type = "bandpass";
      band.Q.value = 1.5;
      band.frequency.setValueAtTime(1200, 0);
      band.frequency.exponentialRampToValueAtTime(4200, seconds);
      const swell = ctx.createGain();
      swell.gain.setValueAtTime(0, 0);
      swell.gain.linearRampToValueAtTime(1, 0.09);
      swell.gain.setValueAtTime(1, 0.16);
      swell.gain.exponentialRampToValueAtTime(0.001, seconds - 0.01);
      source.connect(band).connect(swell).connect(ctx.destination);
      source.start(0);
    }
  });
  normalize(buffer.getChannelData(0), CARD_PEAK);
  return buffer;
}
